<template><div class="page-card"><h2>公告管理</h2><el-button type="primary" @click="create">发布公告</el-button><el-timeline style="margin-top:20px"><el-timeline-item v-for="n in rows" :key="n.id" :timestamp="n.publishedAt||n.createdAt"><h3>{{ n.title }}</h3><p>{{ n.content }}</p></el-timeline-item></el-timeline></div></template>
<script setup>import {ref,onMounted} from 'vue';import http from '../api/http';const rows=ref([]);async function load(){const r=await http.get('/notices/public');rows.value=r.data}async function create(){const title=prompt('公告标题');const content=prompt('公告内容');if(title&&content)await http.post('/notices',{title,content,adminId:JSON.parse(localStorage.getItem('library_user')).id,publishStatus:1}).then(load)}onMounted(load)</script>
